export function mergeAllBangla1Batches(...batches: Chapter[][]): Chapter[] {
  const map = new Map<string, Chapter>();
  for (const batch of batches) {
    for (const ch of batch) {
      const existing = map.get(ch.id);
      if (existing) {
        const existingIds = new Set(existing.mcqs.map((m) => m.id));
        const extra = ch.mcqs.filter((m) => !existingIds.has(m.id));
        existing.mcqs = [...existing.mcqs, ...extra];
      } else {
        map.set(ch.id, { ...ch, mcqs: [...ch.mcqs] });
      }
    }
  }
  return Array.from(map.values());
}

export const HSC_BANGLA_1ST_ALL_2000_CHAPTERS: Chapter[] = mergeAllBangla1Batches(
  [...HSC_BANGLA_1ST_PROSE_CHAPTERS, ...HSC_BANGLA_1ST_POETRY_AND_SAHITYA_CHAPTERS],
  [...HSC_BANGLA_1ST_BATCH2_PROSE_CHAPTERS, ...HSC_BANGLA_1ST_BATCH2_POETRY_CHAPTERS],
  [...HSC_BANGLA_1ST_BATCH3_PROSE_CHAPTERS, ...HSC_BANGLA_1ST_BATCH3_POETRY_CHAPTERS],
  [...HSC_BANGLA_1ST_BATCH4_PROSE_CHAPTERS, ...HSC_BANGLA_1ST_BATCH4_POETRY_CHAPTERS]
);
